RGB hslToRGB(const HSL& hsl) {
    float h = hsl.h / 360.0f;
    float s = hsl.s, l = hsl.l;
    if (s == 0.0f) return RGB(l, l, l);
    float q = l < 0.5f ? (1.0f + s) * l : (l + s) - l * s;
    float p = (l + l) - q;
    auto hue2rgb = [](float p, float q, float t) {
        if (t < 0.0f) t = 1.0f + t;
        if (t > 1.0f) t -= 1.0f;
        if (t < 1.0f/6.0f) return p + (6.0f * (q - p)) * t;
        if (t < 0.5f) return q;
        if (t < 2.0f/3.0f) return p + 6.0f * ((q - p) * (2.0f/3.0f - t));
        return p;
    };
    float r = hue2rgb(p, q, h - 1.0f/3.0f);
    float g = hue2rgb(p, q, h);
    float b = hue2rgb(p, q, h + 1.0f/3.0f);
    return RGB(r, g, b);
