```rust
pub fn format_g(value: f32) -> String {
    let v = value as f64; // exact promotion
    if v.is_nan() { return if v.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if v.is_infinite() { return if v < 0.0 { "-inf".into() } else { "inf".into() }; }
    if v == 0.0 { return if v.is_sign_negative() { "-0".into() } else { "0".into() }; }
    let neg = v < 0.0;
    let a = v.abs();
    // get 6-significant-digit rounding via %.5e
    let s = format!("{:.5e}", a); // e.g. "3.57628e-7"
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect(); // 6 digits
    let out = if exp < -4 || exp >= 6 {
        // scientific: d.ddddd with trailing zeros stripped
        let mut m = String::new();
        m.push(digits.as_bytes()[0] as char);
        let frac = digits[1..].trim_end_matches('0');
        if !frac.is_empty() { m.push('.'); m.push_str(frac); }
        format!("{}e{}{:02}", m, if exp < 0 { "-" } else { "+" }, exp.abs())
    } else if exp >= 0 {
        let ip = &digits[..=exp as usize]; // exp+1 digits
        let frac = digits[exp as usize + 1..].trim_end_matches('0');
        if frac.is_empty() { ip.to_string() } else { format!("{}.{}", ip, frac) }
    } else {
        // 0.000ddd
        let zeros = (-exp - 1) as usize;
        let frac_all = format!("{}{}", "0".repeat(zeros), digits);
        let frac = frac_all.trim_end_matches('0');
        format!("0.{}", frac)
    };
    if neg { format!("-{}", out) } else { out }
}
```

