pub fn rgb_to_hsl(rgb: &RGB) -> HSL {
    let r = rgb.r; let g = rgb.g; let b = rgb.b;
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let l = (max + min) / 2.0;
    let mut h = 0.0f32;
    let mut s = 0.0f32;
    if max != min {
        let d = max - min;
        s = if l > 0.5 { d / ((2.0 - max) - min) } else { d / (max + min) };
        if r == max {
            h = (g - b) / d + if b > g { 6.0 } else { 0.0 };
        } else if g == max {
            h = 2.0 + (b - r) / d;
        } else {
            h = 4.0 + (r - g) / d;
        }
        h = 360.0 * (h / 6.0);
    }
    HSL::new(h, s, l)
}
```

