```rust
pub fn hsl_to_rgb(hsl: &HSL) -> RGB {
    let h = hsl.h / 360.0;
    let s = hsl.s; let l = hsl.l;
    if s == 0.0 { return RGB::new(l, l, l); }
    let q = if l < 0.5 { (1.0 + s) * l } else { (l + s) - l * s };
    let p = (l + l) - q;
    fn hue2rgb(p: f32, q: f32, mut t: f32) -> f32 {
        if t < 0.0 { t = 1.0 + t; }
        if t > 1.0 { t -= 1.0; }
        if t < 1.0/6.0 { return p + (6.0 * (q - p)) * t; }
        if t < 0.5 { return q; }
        if t < 2.0/3.0 { return p + 6.0 * ((q - p) * (2.0/3.0 - t)); }
        p
    }
    let r = hue2rgb(p, q, h + 1.0/3.0);
    let g = hue2rgb(p, q, h);
    let b = hue2rgb(p, q, h - 1.0/3.0);
    RGB::new(r, g, b)
