//! Color types, mirroring the C++ `ColorSpace` library's RGB/HSL structs.
//!
//! All channels are `f32`, exactly as in the original (the C++ classes are
//! `RGB(float, float, float)` and `HSL(float, float, float)`).

/// RGB color with float channels (h: not applicable here; r/g/b in any range).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RGB {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl RGB {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        RGB { r, g, b }
    }
}

/// HSL color: hue in degrees [0, 360), saturation and lightness as floats.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct HSL {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

impl HSL {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        HSL { h, s, l }
    }
}

/// Clamp a value into [min, max], mirroring the C++ `ColorSpace::clamp<T>`:
/// `if (value < min) return min; if (value > max) return max; return value;`
pub fn clamp<T: PartialOrd + Copy>(value: T, min: T, max: T) -> T {
    if value < min {
        min
    } else if value > max {
        max
    } else {
        value
    }
}

//! Color conversions, re-implemented from the observable behavior of the
//! C++ `ColorSpace::ColorConverter` static methods.
//!
//! Every operation is performed in `f32` with the same operand order and
//! association as the original, so results are bit-for-bit identical.

use crate::color::{clamp, HSL, RGB};

/// C++ `std::max(a, b)` is `(a < b) ? b : a` (comparison-based, keeps `a`
/// on ties/NaN), unlike `f32::max`.
fn std_max(a: f32, b: f32) -> f32 {
    if a < b {
        b
    } else {
        a
    }
}

/// C++ `std::min(a, b)` is `(b < a) ? b : a`.
fn std_min(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}

pub struct ColorConverter;

impl ColorConverter {
    /// RGB -> HSL. Hue is returned in degrees (0..360), matching the
    /// original which computes `h = 360.0f * (h / 6.0f)`.
    pub fn rgb_to_hsl(rgb: &RGB) -> HSL {
        let r = rgb.r;
        let g = rgb.g;
        let b = rgb.b;

        let max = std_max(std_max(r, g), b);
        let min = std_min(std_min(r, g), b);
        let l = (max + min) / 2.0;

        let mut h: f32 = 0.0;
        let mut s: f32 = 0.0;

        if max != min {
            let d = max - min;
            s = if l > 0.5 {
                d / ((2.0 - max) - min)
            } else {
                d / (max + min)
            };

            if r == max {
                h = (g - b) / d + if b > g { 6.0 } else { 0.0 };
            } else if g == max {
                h = 2.0 + (b - r) / d;
            } else {
                h = 4.0 + (r - g) / d;
            }
            h = 360.0 * (h / 6.0);
        }

        HSL::new(h, s, l)
    }

    /// HSL -> RGB. Hue is expected in degrees and normalized via `h / 360`.
    pub fn hsl_to_rgb(hsl: &HSL) -> RGB {
        let h = hsl.h / 360.0;
        let s = hsl.s;
        let l = hsl.l;

        if s == 0.0 {
            return RGB::new(l, l, l);
        }

        let q = if l < 0.5 { (1.0 + s) * l } else { (l + s) - l * s };
        let p = (l + l) - q;

        fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
            if t < 0.0 {
                t = 1.0 + t;
            }
            if t > 1.0 {
                t -= 1.0;
            }
            if t < 1.0 / 6.0 {
                return p + (6.0 * (q - p)) * t;
            }
            if t < 0.5 {
                return q;
            }
            if t < 2.0 / 3.0 {
                return p + 6.0 * ((q - p) * (2.0 / 3.0 - t));
            }
            p
        }

        let r = hue_to_rgb(p, q, h + 1.0 / 3.0);
        let g = hue_to_rgb(p, q, h);
        let b = hue_to_rgb(p, q, h - 1.0 / 3.0);

        RGB::new(r, g, b)
    }

    /// Scale the HSL saturation by `value`, clamped to [0, 1].
    pub fn adjust_saturation(color: &RGB, value: f32) -> RGB {
        let mut hsl = Self::rgb_to_hsl(color);
        hsl.s = clamp(hsl.s * value, 0.0, 1.0);
        Self::hsl_to_rgb(&hsl)
    }
}

//! Formatting of floats exactly as C++ `std::cout << float` does by default:
//! the float is promoted to double and printed like `printf("%g", v)` with
//! the default precision of 6 significant digits.

/// Format an `f32` the way `std::ostream::operator<<(float)` does with
/// default flags (defaultfloat, precision 6, no showpoint).
pub fn format_g(value: f32) -> String {
    let v = value as f64; // exact promotion, like C++'s cvtss2sd

    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".into() } else { "nan".into() };
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".into() } else { "inf".into() };
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0".into() } else { "0".into() };
    }

    let neg = v < 0.0;
    let a = v.abs();

    // Round to 6 significant digits via exponential formatting; this yields
    // the same decimal rounding %g performs.
    let sci = format!("{:.5e}", a); // e.g. "3.57628e-7"
    let (mantissa, exp_str) = sci.split_once('e').unwrap();
    let exp: i32 = exp_str.parse().unwrap();
    let digits: String = mantissa.chars().filter(|c| c.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);

    let body = if exp < -4 || exp >= 6 {
        // Scientific notation: strip trailing zeros from the mantissa,
        // exponent is signed and at least two digits (e.g. "1e+06", "3.57628e-07").
        let mut m = String::new();
        m.push(digits.as_bytes()[0] as char);
        let frac = digits[1..].trim_end_matches('0');
        if !frac.is_empty() {
            m.push('.');
            m.push_str(frac);
        }
        format!("{}e{}{:02}", m, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else if exp >= 0 {
        // Fixed notation with all significant digits left of the point.
        let int_part = &digits[..=exp as usize];
        let frac = digits[exp as usize + 1..].trim_end_matches('0');
        if frac.is_empty() {
            int_part.to_string()
        } else {
            format!("{}.{}", int_part, frac)
        }
    } else {
        // Fixed notation, value < 1: leading zeros after the point.
        let zeros = "0".repeat((-exp - 1) as usize);
        let frac = format!("{}{}", zeros, digits);
        format!("0.{}", frac.trim_end_matches('0'))
    };

    if neg {
        format!("-{}", body)
    } else {
        body
    }
}

//! Rust port of /workspace/dataset/color/tests/test9.cpp.
//!
//! Reads optional `r g b [factor]` float arguments, applies
//! `ColorConverter::adjustSaturation`, and prints the resulting RGB
//! channels with C++ `std::cout` default float formatting.

#[path = "src/color.rs"]
mod color;
#[path = "src/converter.rs"]
mod converter;
#[path = "src/fmt.rs"]
mod fmt;

use color::RGB;
use converter::ColorConverter;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut r: f32 = 0.5;
    let mut g: f32 = 0.6;
    let mut b: f32 = 0.7;
    let mut factor: f32 = 1.5;

    if args.len() > 3 {
        r = args[1].parse().expect("invalid float for r");
        g = args[2].parse().expect("invalid float for g");
        b = args[3].parse().expect("invalid float for b");
    }
    if args.len() > 4 {
        factor = args[4].parse().expect("invalid float for factor");
    }

    let rgb = RGB::new(r, g, b);
    let result = ColorConverter::adjust_saturation(&rgb, factor);
    println!(
        "{} {} {}",
        fmt::format_g(result.r),
        fmt::format_g(result.g),
        fmt::format_g(result.b)
    );
}
